<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])){header('Location: login.php');exit;} $config=require __DIR__.'/config.php';function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$rows=$pdo->query('SELECT p.id,p.nombre,p.precio,p.precio_oferta,p.estado,t.nombre AS tienda FROM productos p JOIN tiendas t ON t.id=p.tienda_id ORDER BY p.id DESC')->fetchAll();}catch(Throwable $e){http_response_code(500);exit('No se pudieron cargar los productos.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Productos</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:950px;margin:auto;padding:30px 20px}.card{background:#fff;padding:24px;border-radius:16px}a{color:#886c42}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 7px;border-bottom:1px solid #eee}th{color:#666;font-size:13px}</style></head><body><main><p><a href="panel.php">← Panel</a> · <a href="logout.php">Cerrar sesión</a></p><section class="card"><h1>Productos</h1><p>Selecciona el producto que deseas modificar.</p><table><thead><tr><th>ID</th><th>Producto</th><th>Tienda</th><th>Precio</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h((string)$r['id'])?></td><td><?=h($r['nombre'])?></td><td><?=h($r['tienda'])?></td><td>S/ <?=h((string)$r['precio'])?></td><td><?=h($r['estado'])?></td><td><a href="producto-editar.php?id=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No hay productos registrados.</td></tr><?php endif;?></tbody></table></section></main></body></html>
